library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)
library(readr)

# Load all files
wave1 <- read_delim('data/input/wave_one_lsype_family_background_2020.tab', delim = '\t')
wave2 <- read_delim('data/input/wave_two_lsype_family_background_2020.tab', delim = '\t')
wave3 <- read_delim('data/input/wave_three_lsype_family_background_2020.tab', delim = '\t')
wave4 <- read_delim('data/input/wave_four_lsype_family_background_2020.tab', delim = '\t')
wave5 <- read_delim('data/input/wave_five_lsype_family_background_2020.tab', delim = '\t')
wave6 <- read_delim('data/input/wave_six_lsype_young_person_2020.tab', delim = '\t')
wave7 <- read_delim('data/input/wave_seven_lsype_young_person_2020.tab', delim = '\t')
wave8 <- read_delim('data/input/ns8_2015_main_interview.tab', delim = '\t')
wave9 <- read_delim('data/input/ns9_2022_derived_variables.tab', delim = '\t')

# Function to convert -1 to -8 (Don't know) for waves 1-7
convert_dont_know_1to7 <- function(x) {
  x[x == -1] <- -8
  x
}

# Function to map detailed 8-category to collapsed 6-category for waves 1-4
collapse_tenure_1to4 <- function(x) {
  case_when(
    x %in% c(4, 5, 6) ~ 4,  # Council, Housing Association, Private -> Rent it
    x == 8 ~ 6,  # Some other arrangement -> Other
    x %in% 1:7 ~ x,  # Pass through
    TRUE ~ x
  )
}

# Function to map detailed 8-category to collapsed 6-category for waves 8-9
collapse_tenure_8to9 <- function(x) {
  case_when(
    x %in% 1:5 ~ x,  # Pass through
    x %in% c(6, 7) ~ 6,  # Squatting and Other -> Other (6)
    TRUE ~ x
  )
}

# Function to map detailed 8-category to collapsed 6-category for waves 5-7
collapse_tenure_5to7 <- function(x) {
  case_when(
    x %in% c(4, 5, 6) ~ 4,  # Council, Housing Association, Private -> Rent it
    x %in% 1:3 ~ x,  # Own outright, buying, shared -> pass through
    x == 7 ~ 5,  # Rent free -> Rent it (or keep as is? Let me check)
    x == 8 ~ 6,  # Some other arrangement -> Other
    TRUE ~ x
  )
}

# === WAVES 1-4: Single source variable ===

# Wave 1 (Age 14)
hownteen14 <- convert_dont_know_1to7(wave1$W1hous12HH)
hown14 <- collapse_tenure_1to4(hownteen14)

# Wave 2 (Age 15)
hownteen15 <- convert_dont_know_1to7(wave2$W2Hous12HH)
hown15 <- collapse_tenure_1to4(hownteen15)

# Wave 3 (Age 16)
hownteen16 <- convert_dont_know_1to7(wave3$W3hous12HH)
hown16 <- collapse_tenure_1to4(hownteen16)

# Wave 4 (Age 17)
hownteen17 <- convert_dont_know_1to7(wave4$W4Hous12HH)
hown17 <- collapse_tenure_1to4(hownteen17)

# === WAVES 5-7: Three source variables per sweep ===

# Function to derive tenure from type + subtype variables
derive_tenure_5to7 <- function(type, owned_subtype, rented_subtype) {
  n <- length(type)
  result <- rep(NA_real_, n)

  for (i in seq_len(n)) {
    t <- type[i]
    o <- owned_subtype[i]
    r <- rented_subtype[i]

    # Check if tenure type is substantive (1=Owned, 2=Rented, 3=Something else)
    # Codes 1, 2, 3 are substantive; other codes are missing/not asked
    if (t %in% 1:3) {
      if (t == 1) {
        # Owned
        if (!is.na(o) && o %in% 1:4) {
          if (o == 4) {
            result[i] <- 8  # Some other arrangement
          } else {
            result[i] <- o  # 1=Outright, 2=Buying, 3=Shared
          }
        } else if (!is.na(o)) {
          # Missing code from owned_subtype
          if (o %in% c(-92, -91, -999)) {
            result[i] <- o
          } else if (o == -1) {
            result[i] <- -8  # Don't know
          }
        }
      } else if (t == 2) {
        # Rented
        if (!is.na(r) && r %in% 1:5) {
          if (r %in% 1:3) {
            # Council, Housing Association, Private -> map to 4, 5, 6 in detailed
            result[i] <- r + 3
          } else if (r == 4) {
            result[i] <- 7  # Rent free
          } else if (r == 5) {
            result[i] <- 8  # Some other arrangement
          }
        } else if (!is.na(r)) {
          # Missing code from rented_subtype
          if (r %in% c(-92, -91, -999)) {
            result[i] <- r
          } else if (r == -1) {
            result[i] <- -8  # Don't know
          }
        }
      } else if (t == 3) {
        # Something else
        result[i] <- 8
      }
    } else {
      # Type is not substantive (missing code)
      if (t %in% c(-92, -91, -999)) {
        result[i] <- t
      } else if (t == -1) {
        result[i] <- -8  # Don't know
      }
    }
  }

  result
}

# Wave 5 (Age 18)
hownteen18 <- derive_tenure_5to7(wave5$W5Hous12HH, wave5$W5Hous12BHH, wave5$W5Hous12CHH)
hown18 <- collapse_tenure_5to7(hownteen18)

# Wave 6 (Age 19)
hownteen19 <- derive_tenure_5to7(wave6$W6Hous12YP, wave6$W6Hous12bYP, wave6$W6Hous12cYP)
hown19 <- collapse_tenure_5to7(hownteen19)

# Wave 7 (Age 20)
hownteen20 <- derive_tenure_5to7(wave7$W7Hous12YP, wave7$W7Hous12bYP, wave7$W7Hous12cYP)
hown20 <- collapse_tenure_5to7(hownteen20)

# === WAVES 8-9: Single source variable ===

# Wave 8 (Age 25) - -1 is Not applicable (standard), not Don't know
hown25 <- collapse_tenure_8to9(wave8$W8TENURE)

# Wave 9 (Age 32)
hown32 <- collapse_tenure_8to9(wave9$W9DTENURE)

# === Merge all data ===

merged <- wave1 %>%
  full_join(wave2, by = "NSID") %>%
  full_join(wave3, by = "NSID") %>%
  full_join(wave4, by = "NSID") %>%
  full_join(wave5, by = "NSID") %>%
  full_join(wave6, by = "NSID") %>%
  full_join(wave7, by = "NSID") %>%
  full_join(wave8, by = "NSID") %>%
  full_join(wave9, by = "NSID")

# === Create final output with only ID and derived variables ===

final_output <- merged %>%
  select(NSID,
         hownteen14, hownteen15, hownteen16, hownteen17, hownteen18, hownteen19, hownteen20,
         hown14, hown15, hown16, hown17, hown18, hown19, hown20, hown25, hown32)

# Write output
dir.create('data/output', showWarnings = FALSE, recursive = TRUE)
write_csv(final_output, 'data/output/cleaned_data.csv')

cat('Cleaned data written to data/output/cleaned_data.csv\n')
cat('Number of rows:', nrow(final_output), '\n')
cat('Number of columns:', ncol(final_output), '\n')

