merged$hown14 <- collapse_tenure_1to4(merged$hownteen14)

merged$hownteen15 <- convert_dont_know_1to7(merged$W2Hous12HH)
merged$hown15 <- collapse_tenure_1to4(merged$hownteen15)

merged$hownteen16 <- convert_dont_know_1to7(merged$W3hous12HH)
merged$hown16 <- collapse_tenure_1to4(merged$hownteen16)

merged$hownteen17 <- convert_dont_know_1to7(merged$W4Hous12HH)
merged$hown17 <- collapse_tenure_1to4(merged$hownteen17)

