merged$hown18 <- collapse_tenure_5to7(merged$hownteen18)

merged$hownteen19 <- derive_tenure_5to7(merged$W6Hous12YP, merged$W6Hous12bYP, merged$W6Hous12cYP)
merged$hown19 <- collapse_tenure_5to7(merged$hownteen19)

merged$hownteen20 <- derive_tenure_5to7(merged$W7Hous12YP, merged$W7Hous12bYP, merged$W7Hous12cYP)
merged$hown20 <- collapse_tenure_5to7(merged$hownteen20)

# Waves 8-9: Single source variable
merged$hown25 <- collapse_tenure_8to9(merged$W8TENURE)
merged$hown32 <- collapse_tenure_8to9(merged$W9DTENURE)

# === Create final output with only ID and derived variables ===

